    hub_truefalse_desc: "Tenglikni tekshir",
    hub_lecture_truefalse_title: "Dars: To'g'rimi yoki noto'g'rimi?",
    hub_lecture_truefalse_desc: "Tengliklarni qanday tekshirish",
